        .knockout-final .match,.knockout-bracket.dense .knockout-final .match{position:relative;width:132%;height:82px;min-height:82px;max-height:82px;overflow:visible;justify-self:center;transform:translateY(84px);padding:10px 14px;border:2px solid #d6a9bb;border-left:7px solid #f0c9d8;border-radius:10px;background:linear-gradient(135deg,#65334a,#351a2b);box-shadow:0 0 0 3px rgba(203,132,160,.22),0 0 34px rgba(137,61,91,.58)}.knockout-final .match:before{content:'FINAL';position:absolute;right:0;bottom:calc(100% + 9px);left:0;color:#f2dce5;font-size:15px;font-weight:1000;line-height:1;letter-spacing:.18em;text-align:center;text-shadow:0 2px 10px rgba(0,0,0,.6)}.knockout-final .player,.knockout-final .score,.knockout-bracket.dense .knockout-final .player,.knockout-bracket.dense .knockout-final .score{font-size:12px;font-weight:1000}.knockout-final .player{height:22px;line-height:22px}.knockout-final .player+.player{margin-top:7px}.knockout-final .score{line-height:22px}.champion-spotlight{position:absolute;z-index:4;top:4%;left:50%;display:flex;width:430px;align-items:center;gap:16px;padding:14px 18px;transform:translateX(-50%);border:2px solid #8fb1cc;border-radius:16px;background:linear-gradient(135deg,rgba(31,72,103,.97),rgba(10,31,48,.98));box-shadow:0 14px 38px rgba(0,0,0,.42),0 0 28px rgba(104,161,202,.2)}.champion-visual{position:relative;flex:0 0 108px;height:108px}.champion-trophy{width:108px;height:108px;object-fit:contain}.champion-photo{width:108px;height:108px;border:4px solid #c4d8e7;border-radius:50%;object-fit:cover;background:#10263a}.champion-mini-cup{position:absolute;right:-8px;bottom:-6px;width:40px;height:40px;object-fit:contain;filter:drop-shadow(0 4px 7px rgba(0,0,0,.55))}.champion-copy{min-width:0;text-align:left}.champion-label{color:#a9c7df;font-size:11px;font-weight:1000;letter-spacing:.14em;text-transform:uppercase}.champion-name{margin-top:7px;overflow:hidden;color:#fff;font-size:23px;font-weight:1000;line-height:1.05;text-overflow:ellipsis;text-transform:uppercase}.champion-club{margin-top:8px;color:#c7d8e5;font-size:13px;font-weight:800;line-height:1.2}.champion-spotlight+.knockout-bracket{}.bracket-stage.has-champion .bracket-brand{display:none}
        .knockout-column .player,.knockout-bracket.dense .player{font-size:9px}.knockout-final .player,.knockout-bracket.dense .knockout-final .player{font-size:10px}.set-points{display:flex;flex:none;align-items:center;justify-content:flex-end;gap:2px}.set-point{display:grid;min-width:22px;height:20px;padding:0 3px;place-items:center;border:1px solid #58758d;border-radius:3px;background:#091b2b;color:#fff;font-size:11px;font-weight:1000;line-height:1}.set-point.is-set-winner{border-color:#27a876;background:#0d3b2b;color:#67f0ae;box-shadow:0 0 8px rgba(39,168,118,.25)}.match.called .set-point{border-color:#b78c23;background:#30270f}.match.called .set-point.is-set-winner,.match.in_progress .set-point.is-set-winner{border-color:#34c98c;background:#0d3b2b;color:#75f5ba}.match.in_progress .set-point{border-color:#278b64;background:#0b2a20}.knockout-final .set-point{min-width:24px;height:22px;border-color:#d6a9bb;background:#291420;font-size:12px}.knockout-final .set-point.is-set-winner{border-color:#34c98c;background:#0d3b2b;color:#75f5ba}.mini-score .set-points{gap:4px}.mini-score .set-point{min-width:30px;height:27px;font-size:15px}.zones-grid.single-zone .mini-score .set-point{min-width:34px;height:30px;font-size:18px}.zones-grid.multi-row .mini-score .set-point{min-width:27px;height:25px;font-size:13px}.zones-grid.dense .mini-score .set-point,.zones-grid.crowded .mini-score .set-point{min-width:20px;height:18px;font-size:9px}
    </style>
</head>
<body>
<template id="unavailable-screen">@include('public.partials.competition-availability')</template>
<main id="stage"><div class="empty">Cargando resultados en vivo…</div></main>
<script>
const endpoint=@json($jsonUrl),config=@json($broadcastConfig),trophyImage='data:image/png;base64,{{ base64_encode(file_get_contents(public_path('images/broadcast/championship-cup.png'))) }}',stage=document.querySelector('#stage');
let data=null,slides=[],activeSlide=0,lastPayload='',loading=false,rotationTimer=null;
function fitStage(){const scale=Math.min(window.innerWidth/1920,window.innerHeight/1080);stage.style.transform='translate(-50%,-50%) scale('+scale+')'}
const esc=value=>String(value??'—').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[char]));
function compactPlayerName(value){const text=String(value||'').trim();if(!text)return'';if(text.includes(',')){const [surname,...givenParts]=text.split(','),given=givenParts.join(',').trim();return surname.trim()+', '+(given?given.charAt(0).toLocaleUpperCase('es')+'.':'')}const parts=text.split(/\s+/);if(parts.length<2)return text;const surname=parts.pop(),given=parts.join(' ');return surname.toLocaleUpperCase('es')+', '+given.charAt(0).toLocaleUpperCase('es')+'.'}
function mediaUrl(value){if(!value)return'';try{const url=new URL(value,window.location.origin);return url.host===window.location.host?url.pathname+url.search:url.href}catch{return value}}
const stateLabel=state=>({pending:'Pendiente',ready:'Preparada',in_progress:'En curso',completed:'Finalizada'}[state]||state);
const scheduleDate=schedule=>schedule.starts_at?new Intl.DateTimeFormat('es-AR',{dateStyle:'short',timeStyle:'short'}).format(new Date(schedule.starts_at)):'';
const matchState=match=>['called','in_progress','completed'].includes(match.estado)?match.estado:'';
const score=(match,side)=>{const sets=Array.isArray(match.sets?.sets)?match.sets.sets:[],key=side===0?'player_one_points':'player_two_points',target=Number(match.puntos_por_set||0);return '<span class="set-points">'+(sets.length?sets.map(set=>{const value=set[key]??'—',winner=target>0&&Number(value)===target?' is-set-winner':'';return '<span class="set-point'+winner+'">'+esc(value)+'</span>'}).join(''):'<span class="set-point">—</span>')+'</span>'};
function identity(){return '<header class="identity">'+(data.logo?'<img class="tournament-logo" src="'+esc(data.logo)+'" alt="Logo del torneo">':'')+'<div class="live">Resultados en vivo</div><div class="tournament">'+esc(data.torneo)+'</div><div class="tournament-data"><span><small>Sede</small><b>'+esc(data.sede||'Sin informar')+'</b></span><span><small>Fecha</small><b>'+esc(data.fecha||'Sin informar')+'</b></span><span><small>Tipo</small><b>'+esc([data.tipo_torneo,data.caracter].filter(Boolean).join(' · ')||'Sin informar')+'</b></span><span><small>Modalidad</small><b>'+esc(data.modalidad||'Sin informar')+'</b></span></div></header>'}
function matchCard(match,style='',side='left',showPositions=false){const winner=match.ganador||'',player=(number,name,scoreValue,isWinner,row)=>'<div class="player '+(isWinner?'winner':'')+'">'+(showPositions?'<strong class="grid-position '+row+'">'+esc(number||'—')+'</strong>':'')+'<span>'+esc(/^A designar$|^LIBRE$/i.test(name)?name:compactPlayerName(name))+'</span><b class="score">'+scoreValue+'</b></div>',heading=side!=='center'&&match.mesa?'<div class="match-title"><span class="table">Mesa '+esc(match.mesa)+'</span></div>':'';return '<article class="match '+matchState(match)+(showPositions?' first-round':'')+'"'+(style?' style="'+style+'"':'')+'>'+heading+player(match.numero_1,match.jugador_1||match.placeholder_1||'A designar',score(match,0),winner===match.jugador_1,'top')+player(match.numero_2,match.jugador_2||match.placeholder_2||'A designar',score(match,1),winner===match.jugador_2,'bottom')+'</article>'}
function zoneMatchPosition(match){const label=String(match.etiqueta||'').toLocaleLowerCase('es');if(label==='partido 1')return'z-m1';if(label==='partido 2')return'z-m2';if(label.includes('primer puesto'))return'z-win';if(label.includes('segundo puesto'))return'z-second';if(label.includes('perdedores')||label.includes('recuperación'))return'z-loss';return''}
function miniMatchCard(match){const winner=match.ganador||'',name=value=>value?(/^LIBRE$/i.test(value)?value:compactPlayerName(value)):'A definir';return '<article class="mini-match '+zoneMatchPosition(match)+' '+matchState(match)+'"><div class="mini-title"><span>'+esc(match.etiqueta||('Ronda '+match.ronda))+'</span>'+(match.mesa?'<span class="table">Mesa '+esc(match.mesa)+'</span>':'')+'</div><span class="mini-player '+(winner===match.jugador_1?'winner':'')+'">'+esc(name(match.jugador_1))+'</span><b class="mini-score">'+score(match,0)+'</b><span class="mini-player '+(winner===match.jugador_2?'winner':'')+'">'+esc(name(match.jugador_2))+'</span><b class="mini-score">'+score(match,1)+'</b></article>'}
function zonePanel(phase,zone){const matches=phase.partidos.filter(match=>Number(match.zona_id)===Number(zone.id)),standings=zone.jugadores.slice().sort((a,b)=>(a.clasificacion||99)-(b.clasificacion||99)),first=matches.find(match=>match.etiqueta==='Definición del primer puesto'&&match.estado==='completed')?.ganador||'A definir',second=matches.find(match=>match.etiqueta==='Definición del segundo puesto'&&match.estado==='completed')?.ganador||'A definir';return '<section class="zone-panel"><div class="zone-name"><span>'+esc(zone.nombre)+'</span></div><div class="zone-card-body"><div class="zone-bracket-grid">'+matches.map(miniMatchCard).join('')+'<div class="zone-place z-first-place"><small>1° puesto</small><strong>'+esc(first)+'</strong></div><table class="zone-standings"><thead><tr><th>Pos</th><th>Jugador</th><th>PG</th><th>DS</th><th>Prom</th></tr></thead><tbody>'+standings.map(row=>'<tr><td>'+esc(row.clasificacion)+'</td><td>'+esc(row.nombre)+'</td><td>'+esc(row.partidos_ganados)+'</td><td>'+esc(row.diferencia_sets)+'</td><td>'+esc(row.promedio)+'</td></tr>').join('')+'</tbody></table><div class="zone-place z-runner-place"><small>2.º puesto</small><strong>'+esc(second)+'</strong></div></div></div></section>'}
function zoneScheduleSlides(phase,slotKey,zones){return zones.map((zone,index)=>({key:'zones-'+phase.id+'-'+slotKey+'-'+zone.id,html:'<div class="heading"><div class="phase">'+esc(phase.nombre)+'</div><div class="context">'+esc(zone.horario||'Sin horario')+'</div><div class="zone-tabs">'+zones.map((item,itemIndex)=>'<span class="zone-tab '+(itemIndex===index?'active':'')+'">'+esc(item.nombre)+'</span>').join('')+'</div></div><div class="zones-grid single-zone">'+zonePanel(phase,zone)+'</div>'}))}
function scheduleMatches(phase,schedule){return phase.partidos.filter(match=>{if(Number(match.ronda)!==Number(schedule.round_number))return false;const from=Number(schedule.from_match||0),to=Number(schedule.to_match||0);return (!from||Number(match.orden)>=from)&&(!to||Number(match.orden)<=to)})}
function bracketColumn(matches,side,baseCount,showPositions=false){const span=Math.max(1,Math.floor(baseCount/Math.max(1,matches.length)));return '<section class="knockout-column '+side+'">'+matches.map((match,index)=>matchCard(match,'grid-row:'+(index*span+1)+' / span '+span,side,showPositions)).join('')+'</section>'}
function knockoutBracket(phase){const ordered=phase.partidos.slice().sort((a,b)=>Number(a.ronda)-Number(b.ronda)||Number(a.orden)-Number(b.orden)),roundNumbers=[...new Set(ordered.map(match=>Number(match.ronda)))].sort((a,b)=>a-b);if(!roundNumbers.length)return'';const firstRound=ordered.filter(match=>Number(match.ronda)===roundNumbers[0]),baseCount=Math.max(1,Math.ceil(firstRound.length/2)),lastRound=roundNumbers.at(-1),left=[],right=[];roundNumbers.filter(round=>round!==lastRound).forEach((round,roundIndex)=>{const matches=ordered.filter(match=>Number(match.ronda)===round),half=Math.ceil(matches.length/2),showPositions=roundIndex===0;left.push(bracketColumn(matches.slice(0,half),'left',baseCount,showPositions));right.unshift(bracketColumn(matches.slice(half),'right',baseCount,showPositions))});const finalMatches=ordered.filter(match=>Number(match.ronda)===lastRound),finalSpan=Math.max(1,Math.floor(baseCount/Math.max(1,finalMatches.length))),center='<section class="knockout-column knockout-final">'+finalMatches.map((match,index)=>matchCard(match,'grid-row:'+(index*finalSpan+1)+' / span '+finalSpan,'center')).join('')+'</section>',columns=left.length+1+right.length,dense=baseCount>8||columns>9?' dense':'';return '<div class="knockout-bracket'+dense+'" style="--bracket-columns:'+columns+';--base-count:'+baseCount+'">'+left.join('')+center+right.join('')+'</div>'}
function championSpotlight(){if(!data.campeon)return'';const visual=data.campeon.foto?'<div class="champion-visual"><img class="champion-photo" src="'+esc(mediaUrl(data.campeon.foto))+'" alt="'+esc(data.campeon.nombre)+'"><img class="champion-mini-cup" src="'+esc(trophyImage)+'" alt=""></div>':'<div class="champion-visual"><img class="champion-trophy" src="'+esc(trophyImage)+'" alt="Copa del torneo"></div>';return '<section class="champion-spotlight">'+visual+'<div class="champion-copy"><div class="champion-label">Campeón del torneo</div><div class="champion-name">'+esc(data.campeon.nombre)+'</div><div class="champion-club">'+esc(data.campeon.club||'Club sin informar')+'</div></div></section>'}
function bracketSlides(phase){if(!phase.partidos.length)return[{key:'phase-'+phase.id+'-planned',html:'<div class="heading"><div class="phase">'+esc(phase.nombre)+'</div></div><div class="planned-phase"><div class="planned-card"><small>'+esc(stateLabel(phase.estado))+'</small><strong>Grilla a preparar</strong><p>Enfrentamientos a definir</p></div></div>'}];const champion=championSpotlight();return[{key:'phase-'+phase.id+'-bracket',html:'<div class="bracket-stage '+(champion?'has-champion':'')+'">'+(champion||'<div class="bracket-brand"><img class="bracket-trophy" src="'+esc(trophyImage)+'" alt="Copa del torneo"><div class="bracket-name">'+esc(phase.nombre)+'</div></div>')+knockoutBracket(phase)+'</div>'}]}
function buildSlides(){const allowedPhases=(config.allPhases?data.fases:data.fases.filter(phase=>config.phaseIds.includes(Number(phase.id))));slides=allowedPhases.flatMap(phase=>{if(phase.tipo!=='zones')return bracketSlides(phase);const zones=config.allZoneSlots?phase.zonas:phase.zonas.filter(zone=>(config.zoneSlotKeys||[]).includes(String(zone.horario_clave))),bySlot=zones.reduce((groups,zone)=>{(groups[String(zone.horario_clave||'without_slot')]??=[]).push(zone);return groups},{});return Object.entries(bySlot).flatMap(([slotKey,slotZones])=>zoneScheduleSlides(phase,slotKey,slotZones))});if(activeSlide>=slides.length)activeSlide=0}
function restartRotation(){if(rotationTimer){clearInterval(rotationTimer);rotationTimer=null}if(slides.length>1)rotationTimer=setInterval(()=>{if(slides.length<2)return;activeSlide=(activeSlide+1)%slides.length;showSlide()},config.rotationSeconds*1000)}
function showUnavailable(){if(rotationTimer){clearInterval(rotationTimer);rotationTimer=null}stage.innerHTML=document.getElementById('unavailable-screen').innerHTML}
function showSlide(){if(!config.enabled){showUnavailable();return}if(!slides.length){stage.innerHTML='<div class="empty">No hay contenido seleccionado para la transmisión.</div>';restartRotation();return}const slide=slides[activeSlide],staticClass=slides.length===1?' static':'';stage.innerHTML='<section class="slide'+staticClass+'">'+identity()+'<div class="content">'+slide.html+'</div></section><footer class="broadcast-credit">Powered by <strong>© Hernán Gabriel Menna</strong></footer>';if(slides.length>1&&!rotationTimer)restartRotation()}
function syncConfig(transmission){if(!transmission)return false;const next={enabled:Boolean(transmission.habilitada),allPhases:Boolean(transmission.todas_fases),phaseIds:(transmission.fases||[]).map(Number),allZoneSlots:Boolean(transmission.todos_horarios_zonas),zoneSlotKeys:(transmission.horarios_zonas||[]).map(String),rotationSeconds:Math.max(4,Math.min(60,Number(transmission.segundos||8)))};const changed=JSON.stringify(next)!==JSON.stringify({enabled:config.enabled??true,allPhases:config.allPhases,phaseIds:config.phaseIds,allZoneSlots:config.allZoneSlots,zoneSlotKeys:config.zoneSlotKeys,rotationSeconds:config.rotationSeconds});Object.assign(config,next);return changed}
async function refresh(){if(loading)return;loading=true;try{const separator=endpoint.includes('?')?'&':'?',response=await fetch(endpoint+separator+'_='+Date.now(),{cache:'no-store',headers:{Accept:'application/json'}});if(response.status===404||response.status===403){data=null;lastPayload='';slides=[];showUnavailable();return}if(!response.ok)throw new Error('No fue posible obtener los resultados');const payload=await response.json(),signature=JSON.stringify(payload.data),configChanged=syncConfig(payload.data.transmision);if(signature!==lastPayload||configChanged){const currentKey=slides[activeSlide]?.key;lastPayload=signature;data=payload.data;buildSlides();const sameIndex=slides.findIndex(slide=>slide.key===currentKey);if(sameIndex>=0)activeSlide=sameIndex;if(configChanged)restartRotation();showSlide()}}catch(error){if(!data)showUnavailable()}finally{loading=false}}
fitStage();refresh();window.addEventListener('resize',fitStage);setInterval(()=>{if(!document.hidden)refresh()},4000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)refresh()});
</script>
</body>
</html>
